const request = {
  intake_item_id: String($json.intake_item_id || '').trim(),
  review_action: String($json.review_action || '').trim(),
  review_basis: String($json.review_basis || '').trim(),
  confirmation: String($json.confirmation || '').trim()
};
const values = Object.values(request);
if (values.every(v => v === '')) return [{json:{...request, mode:'view_only'}}];
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(request.intake_item_id)) throw new Error('A valid intake item UUID is required');
if (!['needs_more_evidence','rejected','accepted'].includes(request.review_action)) throw new Error('Review action must be needs_more_evidence, rejected, or accepted');
if (request.review_basis.length < 40) throw new Error('Review basis must contain at least 40 characters');
if (request.confirmation !== 'REVIEW') throw new Error('Type REVIEW in confirmation before submitting an action');
return [{json:{...request, mode:'submit_review'}}];
